#!/usr/bin/env python3
import sqlite3
import json
import sys

def analyze_map(map_path):
    """Analyze Civ6 map and extract all relevant information."""
    conn = sqlite3.connect(map_path)
    cursor = conn.cursor()

    # Get map dimensions
    cursor.execute("SELECT Value FROM MapData WHERE Name='Width'")
    width = int(cursor.fetchone()[0])
    cursor.execute("SELECT Value FROM MapData WHERE Name='Height'")
    height = int(cursor.fetchone()[0])

    print(f"Map dimensions: {width}x{height}")

    # Get all plots
    cursor.execute("SELECT ID, TerrainType, ContinentType, IsImpassable FROM Plots ORDER BY ID")
    plots = cursor.fetchall()

    # Get plot features (mountains, etc.)
    cursor.execute("SELECT PlotIndex, FeatureType FROM PlotFeatures")
    features = {row[0]: row[1] for row in cursor.fetchall()}

    # Get plot resources
    cursor.execute("SELECT PlotIndex, ResourceType FROM PlotResources")
    resources = {row[0]: row[1] for row in cursor.fetchall()}

    # Create map grid
    map_grid = []
    for i, (plot_id, terrain, continent, impassable) in enumerate(plots):
        x = i % width
        y = i // width

        feature = features.get(plot_id, None)
        resource = resources.get(plot_id, None)

        map_grid.append({
            'id': plot_id,
            'x': x,
            'y': y,
            'terrain': terrain,
            'feature': feature,
            'resource': resource,
            'impassable': bool(impassable)
        })

    # Print summary
    print(f"\nTotal tiles: {len(map_grid)}")

    # Count terrain types
    terrain_counts = {}
    for tile in map_grid:
        t = tile['terrain']
        terrain_counts[t] = terrain_counts.get(t, 0) + 1

    print("\nTerrain distribution:")
    for terrain, count in sorted(terrain_counts.items()):
        print(f"  {terrain}: {count}")

    # Count features
    feature_counts = {}
    for tile in map_grid:
        if tile['feature']:
            f = tile['feature']
            feature_counts[f] = feature_counts.get(f, 0) + 1

    if feature_counts:
        print("\nFeatures:")
        for feature, count in sorted(feature_counts.items()):
            print(f"  {feature}: {count}")

    # Count resources
    resource_counts = {}
    for tile in map_grid:
        if tile['resource']:
            r = tile['resource']
            resource_counts[r] = resource_counts.get(r, 0) + 1

    if resource_counts:
        print("\nResources:")
        for resource, count in sorted(resource_counts.items()):
            print(f"  {resource}: {count}")

    # Save to JSON
    output = {
        'width': width,
        'height': height,
        'tiles': map_grid
    }

    with open('/root/map_data.json', 'w') as f:
        json.dump(output, f, indent=2)

    print("\nMap data saved to /root/map_data.json")

    # Print a visual representation of a section
    print(f"\nMap visualization (first 20x20):")
    print("  ", end="")
    for x in range(min(20, width)):
        print(f"{x%10}", end="")
    print()

    for y in range(min(20, height)):
        print(f"{y:2d} ", end="")
        for x in range(min(20, width)):
            tile = map_grid[y * width + x]
            if tile['feature'] == 'FEATURE_MOUNTAINS':
                print('M', end='')
            elif tile['terrain'] == 'TERRAIN_OCEAN':
                print('~', end='')
            elif tile['terrain'] == 'TERRAIN_COAST':
                print('≈', end='')
            elif tile['feature'] == 'FEATURE_FOREST':
                print('T', end='')
            elif tile['feature'] == 'FEATURE_JUNGLE':
                print('J', end='')
            elif tile['terrain'] == 'TERRAIN_GRASS':
                print('.', end='')
            elif tile['terrain'] == 'TERRAIN_PLAINS':
                print('_', end='')
            elif tile['terrain'] == 'TERRAIN_DESERT':
                print('d', end='')
            elif tile['terrain'] == 'TERRAIN_TUNDRA':
                print('t', end='')
            elif tile['terrain'] == 'TERRAIN_SNOW':
                print('s', end='')
            else:
                print('?', end='')
        print()

    conn.close()
    return output

if __name__ == "__main__":
    analyze_map("/data/maps/e2e_test_case_0.Civ6Map")

