#!/usr/bin/env python3
"""Verify the solution is valid and calculate adjacency accurately."""

import json
import sqlite3

def load_map(map_path):
    """Load map data from SQLite database."""
    conn = sqlite3.connect(map_path)
    cursor = conn.cursor()

    cursor.execute("SELECT Width, Height FROM Map")
    width, height = cursor.fetchone()

    cursor.execute("SELECT ID, TerrainType, ContinentType, IsImpassable FROM Plots ORDER BY ID")
    plots = cursor.fetchall()

    cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
    features = {row[0]: row[1] for row in cursor.fetchall()}

    cursor.execute("SELECT ID, ResourceType FROM PlotResources")
    resources = {row[0]: row[1] for row in cursor.fetchall()}

    tiles = {}
    for i, (plot_id, terrain, continent, impassable) in enumerate(plots):
        x = i % width
        y = i // width
        tiles[(x, y)] = {
            'terrain': terrain,
            'feature': features.get(plot_id, None),
            'resource': resources.get(plot_id, None),
            'impassable': bool(impassable)
        }

    conn.close()
    return width, height, tiles

def get_neighbors(x, y):
    """Get all adjacent hexagonal neighbors."""
    if y % 2 == 0:  # Even row
        neighbors = [
            (x-1, y), (x+1, y),
            (x-1, y-1), (x, y-1),
            (x-1, y+1), (x, y+1)
        ]
    else:  # Odd row
        neighbors = [
            (x-1, y), (x+1, y),
            (x, y-1), (x+1, y-1),
            (x, y+1), (x+1, y+1)
        ]
    return neighbors

def visualize_solution(width, height, tiles, placements):
    """Print a visualization of the solution."""
    # Create a map showing placements
    print("\nVisualization:")
    print("   ", end="")
    for x in range(width):
        print(f"{x%10}", end="")
    print()

    for y in range(height):
        print(f"{y:2d} ", end="")
        for x in range(width):
            if (x, y) in placements:
                district = placements[(x, y)]
                if district == 'CITY_CENTER':
                    print('C', end='')
                elif district == 'CAMPUS':
                    print('S', end='')
                elif district == 'HOLY_SITE':
                    print('H', end='')
                elif district == 'COMMERCIAL_HUB':
                    print('$', end='')
                elif district == 'HARBOR':
                    print('P', end='')
                elif district == 'INDUSTRIAL_ZONE':
                    print('I', end='')
                else:
                    print('D', end='')
            else:
                tile = tiles.get((x, y), {})
                if tile.get('feature') == 'FEATURE_MOUNTAINS' or 'MOUNTAIN' in tile.get('terrain', ''):
                    print('M', end='')
                elif tile.get('terrain') == 'TERRAIN_OCEAN':
                    print('~', end='')
                elif tile.get('terrain') == 'TERRAIN_COAST':
                    print('≈', end='')
                elif tile.get('feature') == 'FEATURE_FOREST':
                    print('T', end='')
                elif tile.get('feature') == 'FEATURE_JUNGLE':
                    print('J', end='')
                elif tile.get('terrain', '').startswith('TERRAIN_GRASS'):
                    print('.', end='')
                elif tile.get('terrain', '').startswith('TERRAIN_PLAINS'):
                    print('_', end='')
                else:
                    print(' ', end='')
        print()

def verify_adjacency(tiles, placements):
    """Verify adjacency calculations."""
    print("\nDetailed adjacency verification:")

    for (x, y), district in sorted(placements.items()):
        if district == 'CITY_CENTER':
            continue

        neighbors = get_neighbors(x, y)
        print(f"\n{district} at ({x}, {y}):")

        bonus = 0
        details = []

        for nx, ny in neighbors:
            if (nx, ny) not in tiles:
                continue

            tile = tiles[(nx, ny)]
            neighbor_district = placements.get((nx, ny))

            if neighbor_district:
                print(f"  ({nx}, {ny}): {neighbor_district}")
                details.append(f"({nx},{ny})={neighbor_district}")
            else:
                terrain_desc = tile['terrain']
                if tile['feature']:
                    terrain_desc += f" + {tile['feature']}"
                if tile['resource']:
                    terrain_desc += f" + {tile['resource']}"
                print(f"  ({nx}, {ny}): {terrain_desc}")

        # Calculate based on district type
        if district == 'CAMPUS':
            mountains = sum(1 for nx, ny in neighbors if (nx, ny) in tiles and 'MOUNTAIN' in tiles[(nx, ny)]['terrain'])
            rainforest_reef = sum(1 for nx, ny in neighbors if (nx, ny) in tiles and tiles[(nx, ny)]['feature'] in ['FEATURE_RAINFOREST', 'FEATURE_REEF'])
            other_districts = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] not in ['CAMPUS', 'CITY_CENTER'])

            bonus = mountains + rainforest_reef + (other_districts // 2)
            print(f"  Calculation: {mountains} mountains + {rainforest_reef} rainforest/reef + {other_districts}//2 districts = {bonus}")

        elif district == 'HOLY_SITE':
            mountains = sum(1 for nx, ny in neighbors if (nx, ny) in tiles and 'MOUNTAIN' in tiles[(nx, ny)]['terrain'])
            woods = sum(1 for nx, ny in neighbors if (nx, ny) in tiles and tiles[(nx, ny)]['feature'] in ['FEATURE_FOREST', 'FEATURE_JUNGLE'])

            bonus = mountains + (woods // 2)
            print(f"  Calculation: {mountains} mountains + {woods}//2 woods = {bonus}")

        elif district == 'HARBOR':
            coast_resources = sum(1 for nx, ny in neighbors if (nx, ny) in tiles and tiles[(nx, ny)]['terrain'] == 'TERRAIN_COAST' and tiles[(nx, ny)]['resource'])
            city_center = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] == 'CITY_CENTER')
            other_districts = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] not in ['HARBOR', 'CITY_CENTER'])

            bonus = coast_resources + city_center + (other_districts // 2)
            print(f"  Calculation: {coast_resources} coast resources + {city_center} city center + {other_districts}//2 districts = {bonus}")

        elif district == 'COMMERCIAL_HUB':
            harbors = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] == 'HARBOR')
            other_districts = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] not in ['COMMERCIAL_HUB', 'CITY_CENTER', 'HARBOR'])

            bonus = harbors + (other_districts // 2)
            print(f"  Calculation: {harbors} harbors + {other_districts}//2 districts = {bonus}")

        elif district == 'INDUSTRIAL_ZONE':
            other_districts = sum(1 for nx, ny in neighbors if (nx, ny) in placements and placements[(nx, ny)] not in ['INDUSTRIAL_ZONE', 'CITY_CENTER'])

            bonus = other_districts // 2
            print(f"  Calculation: {other_districts}//2 districts = {bonus}")

        print(f"  BONUS: {bonus}")

def main():
    # Load solution
    with open('/output/scenario_3.json', 'r') as f:
        solution = json.load(f)

    print("Solution loaded:")
    print(json.dumps(solution, indent=2))

    # Load map
    width, height, tiles = load_map("/data/maps/e2e_test_case_0.Civ6Map")

    # Build placements dict
    placements = {}
    placements[tuple(solution['city_center'])] = 'CITY_CENTER'
    for district, pos in solution['placements'].items():
        placements[tuple(pos)] = district

    # Visualize
    visualize_solution(width, height, tiles, placements)

    # Verify
    verify_adjacency(tiles, placements)

if __name__ == "__main__":
    main()

