                (x-1, y-1), (x, y-1),
                (x-1, y+1), (x, y+1)
            ]
        else:
            neighbors = [
                (x-1, y), (x+1, y),
                (x, y-1), (x+1, y-1),
                (x, y+1), (x+1, y+1)
            ]
