#!/usr/bin/env python3
"""
Fixed Civilization 6 District Adjacency Bonus Optimizer
Districts replace underlying terrain features
"""

import json
import sqlite3
import itertools

class Civ6Optimizer:
    def __init__(self, map_path):
        self.load_map(map_path)

    def load_map(self, map_path):
        """Load map data from SQLite database."""
        conn = sqlite3.connect(map_path)
        cursor = conn.cursor()

        cursor.execute("SELECT Width, Height FROM Map")
        self.width, self.height = cursor.fetchone()

        cursor.execute("SELECT ID, TerrainType, ContinentType, IsImpassable FROM Plots ORDER BY ID")
        plots = cursor.fetchall()

        cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
        features = {row[0]: row[1] for row in cursor.fetchall()}

        cursor.execute("SELECT ID, ResourceType FROM PlotResources")
        resources = {row[0]: row[1] for row in cursor.fetchall()}

        self.tiles = {}
        for i, (plot_id, terrain, continent, impassable) in enumerate(plots):
            x = i % self.width
            y = i // self.width
            self.tiles[(x, y)] = {
                'terrain': terrain,
                'feature': features.get(plot_id, None),
                'resource': resources.get(plot_id, None),
                'impassable': bool(impassable)
            }

        conn.close()

    def get_neighbors(self, x, y):
        """Get all adjacent hexagonal neighbors."""
        if y % 2 == 0:
            neighbors = [
                (x-1, y), (x+1, y),
                (x-1, y-1), (x, y-1),
                (x-1, y+1), (x, y+1)
            ]
        else:
            neighbors = [
                (x-1, y), (x+1, y),
                (x, y-1), (x+1, y-1),
                (x, y+1), (x+1, y+1)
            ]
        return [(nx, ny) for nx, ny in neighbors if (nx, ny) in self.tiles]

    def is_valid_placement(self, x, y, district_type=None):
        """Check if a tile is valid for district placement."""
        if (x, y) not in self.tiles:
            return False

        tile = self.tiles[(x, y)]

        if tile['impassable']:
            return False

        if tile['terrain'] == 'TERRAIN_OCEAN':
            return False

        if 'MOUNTAIN' in tile['terrain']:
            return False

        if district_type == 'HARBOR' and tile['terrain'] != 'TERRAIN_COAST':
            return False

        if district_type and district_type != 'HARBOR' and tile['terrain'] == 'TERRAIN_COAST':
            return False

        return True

    def calculate_adjacency(self, x, y, district, placements):
        """Calculate adjacency for a specific district.

        IMPORTANT: Districts replace terrain features, so don't count features
        on tiles that have districts.
        """
        neighbors = self.get_neighbors(x, y)
        bonus = 0

        if district == 'CAMPUS':
            district_count = 0
            for nx, ny in neighbors:
                # Check if there's a district here
                if (nx, ny) in placements:
                    neighbor_district = placements[(nx, ny)]
                    if neighbor_district not in ['CAMPUS', 'CITY_CENTER']:
                        district_count += 1
                else:
                    # No district, check terrain features
                    tile = self.tiles[(nx, ny)]
                    if 'MOUNTAIN' in tile['terrain']:
                        bonus += 1
                    if tile['feature'] in ['FEATURE_RAINFOREST', 'FEATURE_REEF']:
                        bonus += 1
            bonus += district_count // 2

        elif district == 'HOLY_SITE':
            woods_count = 0
            for nx, ny in neighbors:
                if (nx, ny) not in placements:
                    tile = self.tiles[(nx, ny)]
                    if 'MOUNTAIN' in tile['terrain']:
                        bonus += 1
                    if tile['feature'] in ['FEATURE_FOREST', 'FEATURE_JUNGLE']:
                        woods_count += 1
            bonus += woods_count // 2

        elif district == 'COMMERCIAL_HUB':
            district_count = 0
            for nx, ny in neighbors:
                if (nx, ny) in placements:
                    neighbor_district = placements[(nx, ny)]
                    if neighbor_district == 'HARBOR':
                        bonus += 1
                    elif neighbor_district not in ['COMMERCIAL_HUB', 'CITY_CENTER']:
                        district_count += 1
            bonus += district_count // 2

        elif district == 'HARBOR':
            district_count = 0
            for nx, ny in neighbors:
                if (nx, ny) in placements:
                    neighbor_district = placements[(nx, ny)]
                    if neighbor_district == 'CITY_CENTER':
                        bonus += 1
                    elif neighbor_district != 'HARBOR':
                        district_count += 1
                else:
                    tile = self.tiles[(nx, ny)]
                    if tile['terrain'] == 'TERRAIN_COAST' and tile['resource']:
                        bonus += 1
            bonus += district_count // 2

        elif district == 'INDUSTRIAL_ZONE':
            district_count = sum(1 for nx, ny in neighbors
                               if (nx, ny) in placements and
                               placements[(nx, ny)] not in ['INDUSTRIAL_ZONE', 'CITY_CENTER'])
            bonus += district_count // 2

        return bonus

    def calculate_total_adjacency(self, placements):
        """Calculate total adjacency bonus for all placements."""
        total = 0
        adjacencies = {}

        for (x, y), district in placements.items():
            if district == 'CITY_CENTER':
                continue

            bonus = self.calculate_adjacency(x, y, district, placements)
            adjacencies[district] = bonus
            total += bonus

        return total, adjacencies

    def get_workable_tiles(self, city_center):
        """Get all tiles within 3 hexes of city center."""
        cx, cy = city_center
        workable = set()

        from collections import deque
        queue = deque([(cx, cy, 0)])
        visited = {(cx, cy)}

        while queue:
            x, y, dist = queue.popleft()
            workable.add((x, y))

            if dist < 3:
                for nx, ny in self.get_neighbors(x, y):
                    if (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny, dist + 1))

        return workable

    def optimize(self, num_cities, population):
        """Optimize district placement."""
        max_districts = 1 + (population - 1) // 3
        print(f"Population {population} allows {max_districts} districts")

        # Find city center
        land_tiles = [(x, y) for (x, y), tile in self.tiles.items()
                      if self.is_valid_placement(x, y)]

        if not land_tiles:
            return None

        avg_x = sum(x for x, y in land_tiles) / len(land_tiles)
        avg_y = sum(y for x, y in land_tiles) / len(land_tiles)
        city_center = min(land_tiles, key=lambda pos: (pos[0]-avg_x)**2 + (pos[1]-avg_y)**2)

        print(f"City center: {city_center}")

        # Get workable tiles
        workable = self.get_workable_tiles(city_center)
        valid_land = [pos for pos in workable if pos != city_center and self.is_valid_placement(pos[0], pos[1])]
        valid_coast = [pos for pos in workable if pos != city_center and self.is_valid_placement(pos[0], pos[1], 'HARBOR')]

        print(f"Valid land tiles: {len(valid_land)}, Valid coast tiles: {len(valid_coast)}")

        # District types
        district_types = ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'HARBOR', 'INDUSTRIAL_ZONE']

        best_solution = None
        best_score = -1
        tested = 0

        # Try all combinations
        for district_combo in itertools.combinations(district_types, max_districts):
            has_harbor = 'HARBOR' in district_combo
            land_only = [d for d in district_combo if d != 'HARBOR']

            if has_harbor:
                for harbor_pos in valid_coast:
                    for land_positions in itertools.combinations(valid_land, len(land_only)):
                        for land_perm in itertools.permutations(land_only):
                            placements = {city_center: 'CITY_CENTER', harbor_pos: 'HARBOR'}
                            for i, district in enumerate(land_perm):
                                placements[land_positions[i]] = district

                            tested += 1
                            score, adjacencies = self.calculate_total_adjacency(placements)

                            if score > best_score:
                                best_score = score
                                best_solution = (placements.copy(), adjacencies.copy())
                                print(f"  New best: {score} - {list(placements.values())[1:]}")
            else:
                for positions in itertools.combinations(valid_land, max_districts):
                    for district_perm in itertools.permutations(district_combo):
                        placements = {city_center: 'CITY_CENTER'}
                        for i, district in enumerate(district_perm):
                            placements[positions[i]] = district

                        tested += 1
                        score, adjacencies = self.calculate_total_adjacency(placements)

                        if score > best_score:
                            best_score = score
                            best_solution = (placements.copy(), adjacencies.copy())
                            print(f"  New best: {score} - {list(placements.values())[1:]}")

        print(f"\nTested {tested} configurations")
        return best_solution, best_score

def main():
    optimizer = Civ6Optimizer("/data/maps/e2e_test_case_0.Civ6Map")

    solution, score = optimizer.optimize(num_cities=1, population=9)

    if solution:
        placements, adjacencies = solution
        print(f"\nBest solution (score: {score}):")
        print(f"Adjacencies: {adjacencies}")
        print(f"Placements:")
        for pos, district in sorted(placements.items()):
            print(f"  {district}: {pos}")

        # Generate output
        city_center = None
        district_placements = {}

        for pos, district in placements.items():
            if district == 'CITY_CENTER':
                city_center = list(pos)
            else:
                district_placements[district] = list(pos)

        output = {
            "city_center": city_center,
