            'impassable': bool(impassable)
        }

    conn.close()
    return tiles

def get_neighbors(x, y):
    """Get hex neighbors."""
    if y % 2 == 0:
        return [(x-1, y), (x+1, y), (x-1, y-1), (x, y-1), (x-1, y+1), (x, y+1)]
    else:
        return [(x-1, y), (x+1, y), (x, y-1), (x+1, y-1), (x, y+1), (x+1, y+1)]

def is_valid_placement(tiles, x, y, district_type):
    """Check if placement is valid."""
    if (x, y) not in tiles:
        return False, "Tile doesn't exist"

    tile = tiles[(x, y)]

    if tile['impassable']:
        return False, "Impassable"

    if tile['terrain'] == 'TERRAIN_OCEAN':
        return False, "Ocean"

    if 'MOUNTAIN' in tile['terrain']:
        return False, "Mountain"

    if district_type == 'HARBOR' and tile['terrain'] != 'TERRAIN_COAST':
        return False, f"Harbor needs coast, got {tile['terrain']}"

    if district_type and district_type != 'HARBOR' and tile['terrain'] == 'TERRAIN_COAST':
        return False, f"{district_type} can't be on coast"

    return True, "Valid"

def calculate_adjacency(tiles, x, y, district, placements):
    """Calculate adjacency bonus."""
    neighbors = [n for n in get_neighbors(x, y) if n in tiles]
    bonus = 0

    if district == 'CAMPUS':
        district_count = 0
        for nx, ny in neighbors:
            if (nx, ny) in placements:
                if placements[(nx, ny)] not in ['CAMPUS', 'CITY_CENTER']:
                    district_count += 1
            else:
                tile = tiles[(nx, ny)]
                if 'MOUNTAIN' in tile['terrain']:
                    bonus += 1
                if tile['feature'] in ['FEATURE_RAINFOREST', 'FEATURE_REEF']:
                    bonus += 1
        bonus += district_count // 2

    elif district == 'HOLY_SITE':
        woods_count = 0
        for nx, ny in neighbors:
            if (nx, ny) not in placements:
                tile = tiles[(nx, ny)]
                if 'MOUNTAIN' in tile['terrain']:
                    bonus += 1
                if tile['feature'] in ['FEATURE_FOREST', 'FEATURE_JUNGLE']:
                    woods_count += 1
        bonus += woods_count // 2

    elif district == 'COMMERCIAL_HUB':
        district_count = 0
        for nx, ny in neighbors:
            if (nx, ny) in placements:
                if placements[(nx, ny)] == 'HARBOR':
                    bonus += 1
                elif placements[(nx, ny)] not in ['COMMERCIAL_HUB', 'CITY_CENTER']:
                    district_count += 1
        bonus += district_count // 2

    elif district == 'HARBOR':
        district_count = 0
        for nx, ny in neighbors:
            if (nx, ny) in placements:
                if placements[(nx, ny)] == 'CITY_CENTER':
                    bonus += 1
                elif placements[(nx, ny)] != 'HARBOR':
                    district_count += 1
            else:
                tile = tiles[(nx, ny)]
                if tile['terrain'] == 'TERRAIN_COAST' and tile['resource']:
                    bonus += 1
        bonus += district_count // 2

    elif district == 'INDUSTRIAL_ZONE':
        district_count = sum(1 for nx, ny in neighbors
                           if (nx, ny) in placements and
                           placements[(nx, ny)] not in ['INDUSTRIAL_ZONE', 'CITY_CENTER'])
        bonus += district_count // 2

    return bonus

